#!/usr/bin/env node
// Usage: node cli.js <expenses.csv> <policy.json> [--today 2026-10-15]
// Exits 1 when any claim has a blocking issue, so it can gate a submission step.
const fs = require("fs");
const { parseCsv, checkExpenses, toMarkdown } = require("./src/check");

const argv = process.argv.slice(2);
const t = argv.indexOf("--today");
const today = t >= 0 ? argv[t + 1] : undefined;
const [csvFile, policyFile] = argv.filter((a, i) => !a.startsWith("--") && !(t >= 0 && i === t + 1));

if (!csvFile || !policyFile) {
  console.error("Usage: node cli.js <expenses.csv> <policy.json> [--today YYYY-MM-DD]");
  process.exit(2);
}

const rows = parseCsv(fs.readFileSync(csvFile, "utf8"));
const policy = JSON.parse(fs.readFileSync(policyFile, "utf8"));
const findings = checkExpenses(rows, policy, today ? { today } : {});
console.log(toMarkdown(findings, rows.length));
if (findings.some((f) => f.severity === "block")) process.exit(1);

// Checks an expense-claim CSV against a simple policy before it reaches an
// approver. "block" findings must be fixed by the claimant; "review"
// findings are allowed with a reason, but a person has to decide.

// Small RFC 4180 reader: quoted fields, "" escapes, commas and newlines in quotes.
function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = "";
  let quoted = false;
  const s = String(text).replace(/\r\n?/g, "\n");
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quoted) {
      if (ch === '"' && s[i + 1] === '"') {
        field += '"';
        i++;
      } else if (ch === '"') quoted = false;
      else field += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ",") {
      row.push(field);
      field = "";
    } else if (ch === "\n") {
      row.push(field);
      rows.push(row);
      row = [];
      field = "";
    } else field += ch;
  }
  if (field !== "" || row.length) {
    row.push(field);
    rows.push(row);
  }
  const [header, ...body] = rows.filter((r) => r.some((c) => c.trim() !== ""));
  if (!header) return [];
  const keys = header.map((h) => h.trim().toLowerCase());
  return body.map((r) => Object.fromEntries(keys.map((k, i) => [k, (r[i] ?? "").trim()])));
}

const REQUIRED = ["id", "employee", "date", "category", "merchant", "amount", "receipt"];

function validDate(iso) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return null;
  const d = new Date(`${iso}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === iso ? d : null;
}

function checkExpenses(rows, policy, { today = new Date().toISOString().slice(0, 10) } = {}) {
  const findings = [];
  const seen = new Map();
  const limits = policy.categoryLimits || {};
  const add = (row, severity, rule, message) =>
    findings.push({ id: row.id || "?", employee: row.employee || "?", severity, rule, message });

  for (const row of rows) {
    const missing = REQUIRED.filter((k) => !row[k]);
    const amount = Number(row.amount);
    const date = validDate(row.date || "");
    if (missing.length || Number.isNaN(amount) || amount <= 0 || !date) {
      const why = missing.length ? `missing ${missing.join(", ")}` : !date ? `bad date "${row.date}"` : `bad amount "${row.amount}"`;
      add(row, "block", "invalid-row", `Row can't be checked: ${why}.`);
      continue;
    }

    const category = row.category.toLowerCase();
    const hasReceipt = /^(yes|y|true|1)$/i.test(row.receipt);
    if (amount > (policy.receiptRequiredOver ?? Infinity) && !hasReceipt) {
      add(row, "block", "missing-receipt", `Receipt required above ${policy.receiptRequiredOver} (claimed ${amount.toFixed(2)}).`);
    }
    if (row.date > today) add(row, "block", "future-date", `Dated ${row.date}, after today (${today}).`);

    const key = [row.employee, row.date, amount.toFixed(2), row.merchant.toLowerCase()].join("|");
    if (seen.has(key)) add(row, "block", "duplicate", `Same employee, date, merchant and amount as ${seen.get(key)}.`);
    else seen.set(key, row.id);

    if (!(category in limits)) add(row, "review", "unknown-category", `Category "${row.category}" is not in the policy.`);
    else if (amount > limits[category]) {
      add(row, "review", "over-limit", `${amount.toFixed(2)} is over the ${category} limit of ${limits[category]}.`);
    }
    const dow = date.getUTCDay();
    if (policy.flagWeekends && (dow === 0 || dow === 6)) add(row, "review", "weekend", "Weekend expense — check it was business.");
  }
  return findings;
}

function toMarkdown(findings, rowCount) {
  const block = findings.filter((f) => f.severity === "block").length;
  const review = findings.length - block;
  const flagged = new Set(findings.map((f) => f.id)).size;
  const lines = [
    "## Expense check",
    "",
    `${rowCount} claim(s) checked: **${rowCount - flagged} clean**, ${block} blocking issue(s), ${review} item(s) for review.`,
  ];
  const byEmployee = new Map();
  for (const f of findings) byEmployee.set(f.employee, [...(byEmployee.get(f.employee) || []), f]);
  for (const [employee, list] of [...byEmployee].sort((a, b) => a[0].localeCompare(b[0]))) {
    lines.push("", `### ${employee}`, "", "| Claim | Severity | Rule | Detail |", "| --- | --- | --- | --- |");
    for (const f of list) lines.push(`| ${f.id} | ${f.severity === "block" ? "🔴 block" : "🟡 review"} | ${f.rule} | ${f.message.replace(/\|/g, "\\|")} |`);
  }
  return lines.join("\n");
}

module.exports = { parseCsv, checkExpenses, toMarkdown };

const test = require("node:test");
const assert = require("node:assert");
const { parseCsv, checkExpenses, toMarkdown } = require("../src/check");

const policy = { receiptRequiredOver: 25, flagWeekends: true, categoryLimits: { meals: 60, taxi: 80 } };
const row = (o) => ({ id: "C-1", employee: "E-1", date: "2026-10-07", category: "meals", merchant: "Cafe", amount: "20", receipt: "yes", ...o });
const rules = (rows) => checkExpenses(rows, policy, { today: "2026-10-15" }).map((f) => `${f.id}:${f.severity}:${f.rule}`);

test("csv parser handles quotes, escaped quotes, commas and CRLF", () => {
  const rows = parseCsv('id,merchant,amount\r\nC-1,"Hotel, Room 12",180\r\nC-2,"Tool ""Pro""",29\r\n');
  assert.deepStrictEqual(rows, [
    { id: "C-1", merchant: "Hotel, Room 12", amount: "180" },
    { id: "C-2", merchant: 'Tool "Pro"', amount: "29" },
  ]);
});

test("a clean claim has no findings", () => {
  assert.deepStrictEqual(rules([row()]), []);
});

test("missing receipt above the threshold and future dates block", () => {
  assert.deepStrictEqual(rules([row({ amount: "30", receipt: "no" })]), ["C-1:block:missing-receipt"]);
  assert.deepStrictEqual(rules([row({ date: "2026-11-02" })]), ["C-1:block:future-date"]);
});

test("duplicates block and point at the earlier claim", () => {
  const findings = checkExpenses([row({ id: "C-1" }), row({ id: "C-2", merchant: "CAFE" })], policy, { today: "2026-10-15" });
  assert.deepStrictEqual(findings.map((f) => [f.id, f.rule]), [["C-2", "duplicate"]]);
  assert.match(findings[0].message, /as C-1/);
});

test("over-limit, unknown category and weekends go to review, not block", () => {
  assert.deepStrictEqual(rules([row({ category: "taxi", amount: "92" })]), ["C-1:review:over-limit"]);
  assert.deepStrictEqual(rules([row({ category: "software" })]), ["C-1:review:unknown-category"]);
  assert.deepStrictEqual(rules([row({ date: "2026-10-11" })]), ["C-1:review:weekend"]);
});

test("rows that can't be checked are blocked with the reason", () => {
  assert.deepStrictEqual(rules([row({ amount: "abc" }), row({ id: "C-2", date: "2026-02-30" }), row({ id: "C-3", merchant: "" })]), [
    "C-1:block:invalid-row",
    "C-2:block:invalid-row",
    "C-3:block:invalid-row",
  ]);
});

test("markdown summary counts clean claims and groups by employee", () => {
  const rows = [row({ id: "C-1" }), row({ id: "C-2", employee: "E-2", amount: "30", receipt: "no" })];
  const md = toMarkdown(checkExpenses(rows, policy, { today: "2026-10-15" }), rows.length);
  assert.match(md, /2 claim\(s\) checked: \*\*1 clean\*\*, 1 blocking issue\(s\), 0 item\(s\) for review\./);
  assert.match(md, /### E-2\n\n\| Claim/);
});
